<script setup lang="ts">
const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
type Aspect='access'|'economics'|'trust'|'replaceability'
type Side='current'|'open'
type Node={id:string;titleNl:string;titleEn:string;ownerNl:string;ownerEn:string;detailNl:string;detailEn:string;kind:'publisher'|'private'|'layer'|'ai'|'user'}
const aspect=ref<Aspect>('access'),selected=ref<{side:Side,id:string}>({side:'current',id:'private-index'}),failure=ref(false)
const tabs=[
 {id:'access' as Aspect,nl:'Toegang en zeggenschap',en:'Access and control'},
 {id:'economics' as Aspect,nl:'Economie voor makers',en:'Publisher economics'},
 {id:'trust' as Aspect,nl:'Herkomst en vertrouwen',en:'Provenance and trust'},
 {id:'replaceability' as Aspect,nl:'Vervangbaarheid',en:'Replaceability'}
]
const common={
 publishers:{id:'publishers',titleNl:'Uitgevers en kennisproducenten',titleEn:'Publishers and knowledge producers',ownerNl:'Onafhankelijke organisaties en personen',ownerEn:'Independent organizations and people',detailNl:'Publiceren informatie op eigen websites, repositories of andere opslag.',detailEn:'Publish information on their own websites, repositories or other storage.',kind:'publisher'} as Node,
 users:{id:'users',titleNl:'Mensen en toepassingen',titleEn:'People and applications',ownerNl:'De gebruiker kiest een interface',ownerEn:'The user chooses an interface',detailNl:'Ontvangen links, bronnen of een samengesteld antwoord.',detailEn:'Receive links, sources or a synthesized answer.',kind:'user'} as Node
}
const diagrams=computed<Record<Aspect,Record<Side,Node[]>>>(()=>({
 access:{
  current:[common.publishers,{id:'private-index',titleNl:'Private crawl- en kennislaag',titleEn:'Private crawl and knowledge layer',ownerNl:'Iedere AI-aanbieder afzonderlijk',ownerEn:'Each AI provider separately',detailNl:'De aanbieder bepaalt wat wordt gecrawld, bewaard, ververst en doorzoekbaar gemaakt.',detailEn:'The provider decides what is crawled, retained, refreshed and made searchable.',kind:'private'},{id:'ai-provider',titleNl:'Model en interface van dezelfde aanbieder',titleEn:'Model and interface from the same provider',ownerNl:'Eén commerciële of publieke exploitant',ownerEn:'One commercial or public operator',detailNl:'Retrieval, selectie, synthese en presentatie zitten grotendeels in dezelfde verticale keten.',detailEn:'Retrieval, selection, synthesis and presentation largely sit in one vertical stack.',kind:'ai'},common.users],
  open:[common.publishers,{id:'open-layer',titleNl:'Open kennislaag',titleEn:'Open knowledge layer',ownerNl:'Open protocollen, meerdere implementaties',ownerEn:'Open protocols, multiple implementations',detailNl:'Standaardiseert identiteit, ontdekking en herkomst zonder één model of aanbieder verplicht te stellen.',detailEn:'Standardizes identity, discovery and provenance without requiring one model or provider.',kind:'layer'},{id:'competing-ai',titleNl:'Concurrerende AI-systemen',titleEn:'Competing AI systems',ownerNl:'Meerdere uitwisselbare aanbieders',ownerEn:'Multiple replaceable providers',detailNl:'Modellen gebruiken dezelfde open kennisobjecten en kunnen eigen ranking- en vertrouwensbeleid toepassen.',detailEn:'Models use the same open knowledge objects and may apply their own ranking and trust policies.',kind:'ai'},common.users]
 },
 economics:{
  current:[common.publishers,{id:'crawl-answer',titleNl:'Crawlen en antwoord overnemen',titleEn:'Crawl and answer directly',ownerNl:'Private AI-keten',ownerEn:'Private AI stack',detailNl:'De aanbieder kan informatie gebruiken zonder dat een bezoek aan de bron volgt. Licenties en betaalmodellen verschillen per platform.',detailEn:'The provider may use information without a visit to the source. Licensing and payment models differ by platform.',kind:'private'},{id:'limited-return',titleNl:'Beperkte terugstroom',titleEn:'Limited return flow',ownerNl:'Afhankelijk van citaten, links en productontwerp',ownerEn:'Depends on citations, links and product design',detailNl:'De maker ontvangt mogelijk bereik, verkeer, betaling of niets; dit is niet door een open protocol vastgelegd.',detailEn:'The creator may receive reach, traffic, payment or nothing; no open protocol defines the exchange.',kind:'ai'},common.users],
  open:[common.publishers,{id:'publisher-policy',titleNl:'Machineleesbare gebruiksvoorwaarden',titleEn:'Machine-readable usage terms',ownerNl:'Door de uitgever gekozen en door protocollen uitgedrukt',ownerEn:'Chosen by the publisher and expressed through protocols',detailNl:'Kan toestemming, bronvermelding, actualisering en eventueel vergoeding beschrijven. Handhaving blijft een apart vraagstuk.',detailEn:'Can express permission, attribution, updates and potentially compensation. Enforcement remains a separate problem.',kind:'layer'},{id:'accountable-use',titleNl:'Herleidbaar gebruik door AI',titleEn:'Traceable use by AI',ownerNl:'Meerdere aanbieders onder dezelfde basisregels',ownerEn:'Multiple providers under common baseline rules',detailNl:'Gebruik en bronverwijzing kunnen controleerbaarder worden, zonder één verplicht verdienmodel te kiezen.',detailEn:'Use and attribution can become more auditable without imposing one mandatory business model.',kind:'ai'},common.users]
 },
 trust:{
  current:[common.publishers,{id:'opaque-selection',titleNl:'Private selectie en metadata',titleEn:'Private selection and metadata',ownerNl:'De AI-aanbieder',ownerEn:'The AI provider',detailNl:'Buitenstaanders zien beperkt welke versies, relaties en herkomstgegevens in de index zijn behouden.',detailEn:'Outsiders have limited visibility into which versions, relations and provenance data the index retains.',kind:'private'},{id:'combined-trust',titleNl:'Relevantie en vertrouwen in één product',titleEn:'Relevance and trust in one product',ownerNl:'Productbeleid en modelgedrag',ownerEn:'Product policy and model behaviour',detailNl:'Hetzelfde systeem vindt informatie en bepaalt hoe zwaar die wordt gewogen.',detailEn:'The same system finds information and decides how heavily to weigh it.',kind:'ai'},common.users],
  open:[common.publishers,{id:'identity-provenance',titleNl:'Identiteit en herkomst',titleEn:'Identity and provenance',ownerNl:'Ondertekende kennisobjecten en open standaarden',ownerEn:'Signed knowledge objects and open standards',detailNl:'Maakt zichtbaar wie iets publiceerde, welke versie is gebruikt en of het object is gewijzigd. Het bewijst niet dat een claim waar is.',detailEn:'Shows who published something, which version was used and whether the object changed. It does not prove a claim true.',kind:'layer'},{id:'separate-trust',titleNl:'Meerdere vertrouwens- en rankingstelsels',titleEn:'Multiple trust and ranking systems',ownerNl:'Gebruiker, domein of AI-aanbieder kiest',ownerEn:'Chosen by user, domain or AI provider',detailNl:'Een medische assistent kan andere bewijsregels gebruiken dan een winkel- of restaurantassistent.',detailEn:'A medical assistant may use different evidence policies from a shopping or restaurant assistant.',kind:'ai'},common.users]
 },
 replaceability:{
  current:[common.publishers,{id:'duplicated-stack',titleNl:'Herhaalde private infrastructuur',titleEn:'Duplicated private infrastructure',ownerNl:'Elke aanbieder bouwt opnieuw',ownerEn:'Each provider rebuilds it',detailNl:'Nieuwe modellen moeten crawling, opslag, indexering en relaties grotendeels opnieuw organiseren.',detailEn:'New models must largely recreate crawling, storage, indexing and relationships.',kind:'private'},{id:'single-provider',titleNl:'Aanbieder als toegangspoort',titleEn:'Provider as gateway',ownerNl:'Kennislaag en model zijn verweven',ownerEn:'Knowledge layer and model are intertwined',detailNl:'Bij prijswijziging, uitsluiting of uitval is overstappen moeilijker omdat ook de toegangsinfrastructuur verandert.',detailEn:'Price changes, exclusion or failure make switching harder because the access infrastructure changes too.',kind:'ai'},common.users],
  open:[common.publishers,{id:'durable-layer',titleNl:'Duurzame open kennisobjecten',titleEn:'Durable open knowledge objects',ownerNl:'Repliceerbare opslag en protocollen',ownerEn:'Replicable storage and protocols',detailNl:'De kennisidentiteit blijft bestaan wanneer opslag, index of embeddingmodel wordt vervangen.',detailEn:'Knowledge identity survives replacement of storage, index or embedding model.',kind:'layer'},{id:'replaceable-ai',titleNl:'Vervangbaar model en interface',titleEn:'Replaceable model and interface',ownerNl:'Concurrentie boven de kennislaag',ownerEn:'Competition above the knowledge layer',detailNl:'Een nieuwe aanbieder kan dezelfde open laag gebruiken zonder de hele informatie-infrastructuur opnieuw op te bouwen.',detailEn:'A new provider can use the same open layer without rebuilding the entire information infrastructure.',kind:'ai'},common.users]
 }
}))
const activeNode=computed(()=>diagrams.value[aspect.value][selected.value.side].find(n=>n.id===selected.value.id)||diagrams.value[aspect.value][selected.value.side][1])
const comparisons=computed(()=>({
 access:{current:nl.value?'Verticale private ketens':'Vertical private stacks',open:nl.value?'Gedeelde laag, concurrerende interfaces':'Shared layer, competing interfaces'},
 economics:{current:nl.value?'Terugstroom door productkeuze':'Return flow set by product design',open:nl.value?'Voorwaarden kunnen protocolmatig zichtbaar zijn':'Terms can be visible at protocol level'},
 trust:{current:nl.value?'Herkomst en ranking grotendeels intern':'Provenance and ranking largely internal',open:nl.value?'Herkomst gedeeld, vertrouwen blijft pluralistisch':'Shared provenance, plural trust'},
 replaceability:{current:nl.value?'Overstappen vervangt ook infrastructuur':'Switching also replaces infrastructure',open:nl.value?'Model vervangbaar zonder kennislaag te vervangen':'Replace model without replacing knowledge layer'}
})[aspect.value])
function chooseAspect(id:Aspect){aspect.value=id;selected.value={side:'current',id:diagrams.value[id].current[1].id};failure.value=false}
function select(side:Side,node:Node){selected.value={side,id:node.id}}
</script>

<template>
 <section class="knowledge-explorer">
  <header><div><p>{{nl?'Interactieve architectuurvergelijking':'Interactive architecture comparison'}}</p><h3>{{nl?'Wie beheert de weg van publicatie naar antwoord?':'Who controls the path from publication to answer?'}}</h3></div><button type="button" @click="chooseAspect('access')">{{nl?'Herstel beginweergave':'Reset view'}}</button></header>
  <nav :aria-label="nl?'Vergelijkingsperspectief':'Comparison perspective'"><button v-for="tab in tabs" :key="tab.id" :class="{active:aspect===tab.id}" @click="chooseAspect(tab.id)">{{nl?tab.nl:tab.en}}</button></nav>
  <p class="intro">{{nl?'Klik op een laag om te zien wat zij doet, wie haar beheert en welke afhankelijkheid ontstaat.':'Select a layer to see what it does, who controls it and which dependency it creates.'}}</p>
  <div class="architectures">
   <article v-for="side in (['current','open'] as Side[])" :key="side" :class="['architecture',side,{failed:failure&&side==='current'&&aspect==='replaceability'}]">
    <div class="architecture-head"><span>{{side==='current'?(nl?'Veelgebruikte huidige architectuur':'Common current architecture'):(nl?'Mogelijke open architectuur':'Possible open architecture')}}</span><b>{{side==='current'?comparisons.current:comparisons.open}}</b></div>
    <div class="flow">
     <template v-for="(node,index) in diagrams[aspect][side]" :key="node.id">
      <button type="button" :class="['node',node.kind,{active:selected.side===side&&selected.id===node.id}]" @click="select(side,node)"><span>{{nl?node.titleNl:node.titleEn}}</span><small>{{nl?node.ownerNl:node.ownerEn}}</small></button>
      <span v-if="index<diagrams[aspect][side].length-1" class="arrow" aria-hidden="true">↓</span>
     </template>
    </div>
    <p v-if="failure&&side==='current'&&aspect==='replaceability'" class="failure-note">{{nl?'De toegangsketen valt mee uit of moet bij een overstap grotendeels opnieuw worden opgebouwd.':'The access stack fails with the provider or must largely be rebuilt when switching.'}}</p>
    <p v-if="failure&&side==='open'&&aspect==='replaceability'" class="failure-note resilient">{{nl?'Een andere AI-interface kan dezelfde open kennisobjecten en protocollen blijven gebruiken.':'Another AI interface can continue using the same open knowledge objects and protocols.'}}</p>
   </article>
  </div>
  <button v-if="aspect==='replaceability'" class="failure-toggle" type="button" :aria-pressed="failure" @click="failure=!failure">{{failure?(nl?'Herstel aanbieder':'Restore provider'):(nl?'Simuleer uitval of overstap':'Simulate failure or switching')}}</button>
  <aside class="detail"><div><span>{{selected.side==='current'?(nl?'Huidige keten':'Current stack'):(nl?'Open alternatief':'Open alternative')}}</span><h4>{{nl?activeNode.titleNl:activeNode.titleEn}}</h4></div><p>{{nl?activeNode.detailNl:activeNode.detailEn}}</p></aside>
  <div class="layer-principles"><div><b>{{nl?'Identiteit':'Identity'}}</b><span>{{nl?'Welk kennisobject en welke versie?':'Which knowledge object and version?'}}</span></div><div><b>{{nl?'Ontdekking':'Discovery'}}</b><span>{{nl?'Wat is semantisch relevant?':'What is semantically relevant?'}}</span></div><div><b>{{nl?'Herkomst':'Provenance'}}</b><span>{{nl?'Wie publiceerde of wijzigde het?':'Who published or changed it?'}}</span></div><div><b>{{nl?'Vertrouwen':'Trust'}}</b><span>{{nl?'Welke bewijs- en rankingregels passen hier?':'Which evidence and ranking rules fit here?'}}</span></div></div>
  <details><summary>{{nl?'Wat dit schema niet beweert':'What this diagram does not claim'}}</summary><p>{{nl?'Een open laag is niet automatisch decentraal, eerlijk, goedkoop of betrouwbaar. Zij lost waarheid, auteursrecht, privacy, verwijdering, financiering en misbruik niet vanzelf op. Het schema onderzoekt scheiding en vervangbaarheid als architectuureigenschappen.':'An open layer is not automatically decentralized, fair, cheap or trustworthy. It does not automatically solve truth, copyright, privacy, removal, funding or abuse. The diagram explores separation and replaceability as architectural properties.'}}</p></details>
 </section>
</template>

