;color:#7e8b86;font-size:1rem}.failure-note{margin:.6rem 0 0;padding:.5rem;border-left:3px solid var(--private);background:#f7eeea}.failure-note.resilient{border-color:var(--open);background:#eaf3ef}.failure-toggle{display:block;margin:.75rem auto}.detail{display:grid;grid-template-columns:minmax(150px,.5fr) 1.5fr;gap:1rem;margin-top:.8rem;padding:.8rem;background:#183c36;color:#fff;border-radius:11px}.detail span{font-size:.58rem;opacity:.7;text-transform:uppercase}.detail h4{margin:.15rem 0;font:750 .9rem system-ui}.detail p{margin:0;opacity:.88}.layer-principles{display:grid;grid-template-columns:repeat(4,1fr);gap:.45rem;margin-top:.75rem}.layer-principles div{display:grid;gap:.15rem;padding:.6rem;background:#edf2ef;border-radius:8px}.layer-principles b{font-size:.68rem}.layer-principles span{font-size:.59rem;color:var(--muted)}.knowledge-explorer>details{margin-top:.75rem;padding:.65rem .75rem;border:1px solid var(--line);border-radius:9px;background:#fff}.knowledge-explorer summary{cursor:pointer;font-weight:700}.knowledge-explorer details p{margin:.45rem 0 0;color:var(--muted);font-size:.67rem}@media(max-width:720px){.knowledge-explorer>header,.architectures,.detail{grid-template-columns:1fr;display:grid}.knowledge-explorer header button{justify-self:start}.layer-principles{grid-template-columns:1fr 1fr}}@media(max-width:430px){.layer-principles{grid-template-columns:1fr}.knowledge-explorer nav{display:grid;grid-template-columns:1fr 1fr}.knowledge-explorer nav button{border-radius:8px}}
